<div class="page-title"><div><em>PROFILE</em><h1>Settings</h1><p>Manage your personal details, preferences and security.</p></div></div><div class="grid settings-grid"><nav class="panel settings-nav"><a class="active">♙ Personal information</a><a>♢ Notifications</a><a>✓ Security & login</a><a>◎ Language & region</a></nav><section class="panel settings-form"><h2>Personal information</h2><p>Keep your contact information up to date.</p><?=form_open_multipart('settings')?><div class="profile-row"><?php if(!empty($profile['avatar_path'])):?><img class="avatar big avatar-image" src="<?=base_url($profile['avatar_path'])?>" alt="Profile photo"><?php else:?><span class="avatar big"><?=initials($profile['first_name'].' '.$profile['last_name'])?></span><?php endif?><div><b>Profile photo</b><small>JPG, PNG or WebP, up to <?=number_format($this->config->item('max_upload_kb')/1024,0)?>MB</small></div><label class="outline file-button">Change photo<input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></label></div><div class="form-grid"><div><label>First name</label><input name="first_name" value="<?=html_escape($profile['first_name'])?>" required></div><div><label>Last name</label><input name="last_name" value="<?=html_escape($profile['last_name'])?>" required></div><div><label>Email address</label><input name="email" type="email" value="<?=html_escape($profile['email'])?>" required></div><div><label>Phone number</label><input name="phone" value="<?=html_escape($profile['phone'])?>"></div><div><label>City</label><input name="city" value="<?=html_escape($profile['city'])?>"></div><div><label>Country</label><input name="country" value="<?=html_escape($profile['country'])?>"></div></div><label>Home address</label><input name="address" value="<?=html_escape($profile['address'])?>"><button class="btn">Save changes</button></form></section></div>
